    83  protected int
    84  file_printf(struct magic_set *ms, const char *fmt, ...)
    85  {
    86          int rv;
    87          va_list ap;
    88
    89          va_start(ap, fmt);
    90          rv = file_vprintf(ms, fmt, ap);
    91          va_end(ap);
    92          return rv;
    93  }
